cards.extra:
echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./mcpserver) || exit 1; for i in $I; do case $i in context|crypto/subtle|encoding/json|errors|fmt|net/http|slices|strings|github.com/modelcontextprotocol/go-sdk/mcp|morphstudio/control|morphstudio/queue) ;; *) echo "imports: package mcpserver imports $i (allowed: context, crypto/subtle, encoding/json, errors, fmt, net/http, slices, strings, github.com/modelcontextprotocol/go-sdk/mcp, morphstudio/control, morphstudio/queue)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' mcpserver/pm.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' mcpserver/pm.go 2>&1); [ -z "$C" ] || { echo "clock: mcpserver/pm.go reads time.Now or time.Since (package mcpserver reads no clock)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head http.ListenAndServe http.ListenAndServeTLS; do C=$(gofmt -l -r "$x -> http.NoBody" mcpserver/pm.go 2>&1); [ -z "$C" ] || { echo "net: mcpserver/pm.go uses $x (no HTTP client and never a listener in package mcpserver)"; exit 1; }; done

echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./daemon) || exit 1; for i in $I; do case $i in context|encoding/json|errors|fmt|net/http|os|path/filepath|sort|strconv|strings|sync|time|unicode/utf8|morphstudio/stream|morphstudio/session|morphstudio/eventlog|morphstudio/telegram|morphstudio/runner|morphstudio/queue|morphstudio/claude|morphstudio/github|morphstudio/bootstrap|morphstudio/registry|morphstudio/gitrules|morphstudio/control|morphstudio/supervisor) ;; *) echo "imports: package daemon imports $i (allowed: context, encoding/json, errors, fmt, net/http, os, path/filepath, sort, strconv, strings, sync, time, unicode/utf8, morphstudio/stream, morphstudio/session, morphstudio/eventlog, morphstudio/telegram, morphstudio/runner, morphstudio/queue, morphstudio/claude, morphstudio/github, morphstudio/bootstrap, morphstudio/registry, morphstudio/gitrules, morphstudio/control, morphstudio/supervisor)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' daemon/daemon.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' daemon/daemon.go 2>&1)$(gofmt -l -r 'time.Until -> time.Time' daemon/daemon.go 2>&1); [ -z "$C" ] || { echo "clock: daemon/daemon.go reads time.Now, time.Since or time.Until (package daemon reads no clock: every time is a call of Deps.Now)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head http.ListenAndServe http.ListenAndServeTLS; do C=$(gofmt -l -r "$x -> http.NoBody" daemon/daemon.go 2>&1); [ -z "$C" ] || { echo "net: daemon/daemon.go uses $x (no HTTP client of its own and never a listener in package daemon: GitHub through Deps.GitHubDo)"; exit 1; }; done

echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./daemon) || exit 1; for i in $I; do case $i in context|encoding/json|errors|fmt|net/http|os|path/filepath|sort|strconv|strings|sync|time|unicode/utf8|morphstudio/stream|morphstudio/session|morphstudio/eventlog|morphstudio/telegram|morphstudio/runner|morphstudio/queue|morphstudio/claude|morphstudio/github|morphstudio/bootstrap|morphstudio/registry|morphstudio/gitrules|morphstudio/control|morphstudio/supervisor) ;; *) echo "imports: package daemon imports $i (allowed: context, encoding/json, errors, fmt, net/http, os, path/filepath, sort, strconv, strings, sync, time, unicode/utf8, morphstudio/stream, morphstudio/session, morphstudio/eventlog, morphstudio/telegram, morphstudio/runner, morphstudio/queue, morphstudio/claude, morphstudio/github, morphstudio/bootstrap, morphstudio/registry, morphstudio/gitrules, morphstudio/control, morphstudio/supervisor)"; exit 1;; esac; done
echo '== clock'; C=$(gofmt -l -r 'time.Now -> time.Time' daemon/pump.go 2>&1)$(gofmt -l -r 'time.Since -> time.Time' daemon/pump.go 2>&1)$(gofmt -l -r 'time.Until -> time.Time' daemon/pump.go 2>&1); [ -z "$C" ] || { echo "clock: daemon/pump.go reads time.Now, time.Since or time.Until (package daemon reads no clock: every time is a call of Deps.Now)"; exit 1; }
echo '== net'; for x in http.DefaultClient http.Get http.Post http.PostForm http.Head http.ListenAndServe http.ListenAndServeTLS; do C=$(gofmt -l -r "$x -> http.NoBody" daemon/pump.go 2>&1); [ -z "$C" ] || { echo "net: daemon/pump.go uses $x (no HTTP client of its own and never a listener in package daemon: GitHub through Deps.GitHubDo)"; exit 1; }; done

echo '== imports'; I=$(go list -e -overlay $P/overlay.json -f '{{join .Imports " "}}' ./cmd/morphd) || exit 1; for i in $I; do case $i in bufio|context|crypto/rand|encoding/hex|errors|flag|fmt|log|net/http|os|path/filepath|strconv|strings|time|morphstudio/stream|morphstudio/runner|morphstudio/queue|morphstudio/eventlog|morphstudio/telegram|morphstudio/github|morphstudio/claude|morphstudio/session|morphstudio/bootstrap|morphstudio/registry|morphstudio/gitrules|morphstudio/control|morphstudio/supervisor|morphstudio/api|morphstudio/mcpserver|morphstudio/daemon) ;; *) echo "imports: package cmd/morphd imports $i (allowed: bufio, context, crypto/rand, encoding/hex, errors, flag, fmt, log, net/http, os, path/filepath, strconv, strings, time, morphstudio/stream, morphstudio/runner, morphstudio/queue, morphstudio/eventlog, morphstudio/telegram, morphstudio/github, morphstudio/claude, morphstudio/session, morphstudio/bootstrap, morphstudio/registry, morphstudio/gitrules, morphstudio/control, morphstudio/supervisor, morphstudio/api, morphstudio/mcpserver, morphstudio/daemon)"; exit 1;; esac; done
echo '== listen'; C=$(gofmt -l -r 'http.ListenAndServe -> http.NoBody' cmd/morphd/main.go 2>&1); [ -n "$C" ] || { echo "listen: cmd/morphd/main.go never calls http.ListenAndServe (the record: one listener on 127.0.0.1)"; exit 1; }; grep -q '"127\.0\.0\.1:' cmd/morphd/main.go || { echo 'listen: cmd/morphd/main.go has no string literal beginning "127.0.0.1: (morphd listens on 127.0.0.1 only)'; exit 1; }
echo '== donewait'; grep -q 'DoneWait' cmd/morphd/main.go || { echo 'donewait: cmd/morphd/main.go never sets daemon.Config.DoneWait (the record: time.Duration(DoneWait) * time.Second)'; exit 1; }
